def filt(d):
    try:
        if len(d)>=8 and all(chr(b) in _A for b in d[:4096]) and len(d)%4==0:
            dec=base64.b64decode(d,validate=True)
            if base64.b64encode(dec)==d: return b'\x01'+dec
    except Exception: pass
    return b'\x00'+d
def unfilt(d):
    return base64.b64encode(d[1:]) if d[0]==1 else d[1:]

