def filt(d):
    b=bytearray(d); i=0; n=len(b)
    while i+5<=n:
        if b[i]==0xE8 or b[i]==0xE9:
            rel=int.from_bytes(b[i+1:i+5],'little')
            b[i+1:i+5]=((rel+i+5)&0xFFFFFFFF).to_bytes(4,'little')
            i+=5
        else: i+=1
    return bytes(b)
def unfilt(d):
    b=bytearray(d); i=0; n=len(b)
    while i+5<=n:
        if b[i]==0xE8 or b[i]==0xE9:
            a=int.from_bytes(b[i+1:i+5],'little')
            b[i+1:i+5]=((a-i-5)&0xFFFFFFFF).to_bytes(4,'little')
            i+=5
        else: i+=1
    return bytes(b)
